"""Generate consistent DOCX/PDF reports from the measured data."""
from pathlib import Path
from xml.sax.saxutils import escape
import csv
import json
from docx import Document
from docx.shared import Pt, Inches
from reportlab.lib import colors
from reportlab.lib.pagesizes import A4
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.ttfonts import TTFont
from reportlab.platypus import SimpleDocTemplate, Paragraph, Table, TableStyle, Spacer, Image

root = Path(__file__).resolve().parents[1]
rows = list(csv.DictReader((root / 'report/measurements.csv').open(encoding='utf-8')))
env = json.loads((root / 'report/environment.json').read_text())
assert len(rows) == 72
assert {int(r['threads']) for r in rows} == {1, 2, 4, 8, 12, 32, 64, 128}
assert all(int(r['observed_peak']) <= int(r['created_incl_main']) <= int(r['threads']) for r in rows)
blocks = []
def heading(s): blocks.append(('h', s))
def para(s): blocks.append(('p', s))
def table(data): blocks.append(('t', data))

heading('Лабораторная работа №2. Управление потоками')
para('Вихарев Лев Александрович, М8О-214БВ-25. Вариант 3: ((3 − 1) % 20) + 1 = 3.')
heading('Цель и постановка задачи')
para('Реализовать последовательную и параллельную сортировку слиянием массива целых чисел на языке C, ограничить количество потоков параметром запуска, продемонстрировать их средствами ОС и исследовать ускорение и эффективность при разных входных данных и числе потоков.')
para('С учётом дополнительных указаний преподавателя в программе отсутствуют функции стандартной библиотеки C для ввода-вывода, выделения памяти, строк, преобразования чисел и генерации случайных данных. Использованы POSIX-интерфейсы write, mmap, munmap, clock_gettime, sysconf, _exit и POSIX Threads. Заголовки с определениями типов и констант не исключаются. POSIX-вызовы доступны через системную C-библиотеку; программа не является двоичным файлом без libc. Независимый тестовый стенд использует qsort и стандартную библиотеку вне сдаваемой программы.')
heading('Алгоритм и функции')
para('merge_sort рекурсивно делит полуинтервал [left, right) пополам, сортирует обе половины и объединяет их функцией merge. Слияние сначала записывается в буфер, затем переносится в исходный массив. Время последовательной версии O(n log n), дополнительный буфер O(n), глубина рекурсии O(log n). Память стеков зависит также от числа потоков.')
para('parallel_sort при длине участка не меньше 16384 и наличии бюджета создаёт один поток для левой половины, а правую сортирует текущий. После pthread_join выполняется слияние. Если участок меньше порога или бюджет исчерпан, вызывается merge_sort. Отдельные слияния не распараллеливаются.')
para('threads_left изначально равен P−1. Проверка и уменьшение выполняются под мьютексом, бюджет не пополняется после завершения ребёнка. Таким образом, за весь запуск создаётся не больше P потоков с учётом главного. Это более строгое ограничение, чем максимум одновременно существующих потоков. Ожидающий родитель продолжает существовать и входит в предел. Фактическое число созданных потоков печатается отдельно от лимита.')
para('Потоки используют непересекающиеся участки исходного массива и буфера. Мьютекс защищает только бюджет, pthread_join обеспечивает завершение ребёнка перед чтением его результата. ThreadArgs передаёт адреса общих массивов и границы; структура на стеке родителя действительна до join. Распределение бюджета зависит от порядка выполнения ветвей планировщиком, поэтому дерево может быть несимметричным.')
para('main создаёт через mmap один блок для двух одинаковых копий массива и буфера, заполняет данные собственным 32-битным генератором с начальным состоянием 42, сортирует копии последовательно и параллельно, проверяет результаты и освобождает память через munmap. read_number разбирает десятичные цифры вручную с проверкой переполнения. equal сравнивает строки, write_text обрабатывает короткие записи и EINTR, print_int и print_value форматируют числа без printf. При ошибке pthread код ошибки печатается числом, процесс завершается через _exit.')
heading('Сборка, запуск и демонстрация')
para('В Linux/WSL: make; ./merge 4 1000000. Формат: ./merge THREADS [SIZE] [random|sorted|reverse|manual]. Диапазон аргумента потоков 1–4096, размер по умолчанию 5 000 000. Для маленькой демонстрации: ./merge 4 10 reverse. До 20 элементов печатаются исходный и отсортированный массивы; в остальных случаях — размер, лимит, число созданных потоков, логические процессоры, оба времени в мс, S, E и Check: OK/FAILED. При нехватке ресурсов pthread процесс сообщает об ошибке; измерение не подменяется успешным результатом.')
para('Для проверки на собственных данных: ./merge 4 5 manual, затем ввести 7 −2 10 0 7 и нажать Enter. Результат: −2 0 7 7 10. Альтернативно: ./merge 4 5 manual < examples/manual.txt. В файле только элементы; размер задаётся аргументом. read_int читает через POSIX read, допускает знаки, пробелы и переводы строк, проверяет диапазон int и преждевременный EOF. Читаются первые SIZE чисел. Ввод выполняется до измерений и одинаково копируется в оба массива; отдельные новые эксперименты для демонстрационного режима в таблицы не добавлялись.')
para('python3 tools/check_threads.py наблюдает Threads в /proc/PID/status и выводит снимок ps -T для четырёх потоков. Для ручного наблюдения можно запустить ./merge 4 10000000 в фоне и повторять ps -T -p PID. Начальная последовательная часть и финальное слияние используют один поток. Сэмплирование может пропустить короткоживущие потоки; число созданий дополнительно учитывает сама программа.')
para('make test: 45 сравнений функций с независимой qsort, 38 проверок интерфейса запуска и 15 проверок ручного ввода — всего 98. Включены предел 1024 на коротком массиве, границы int, размеры вокруг порога, знаки, CRLF, преждевременный EOF и неправильные аргументы. Проверяется отсутствие запрещённых библиотечных вызовов в исполняемом файле через nm. Дополнительно проверен тестовый стенд с AddressSanitizer и UndefinedBehaviorSanitizer. Эти проверки не являются математическим доказательством отсутствия всех ошибок.')
heading('Методика эксперимента и метрики')
para(f"Среда: {env['cpu_model']}; {env['logical_cpus']} логических процессоров; {env['platform']}; {env['compiler']}. Оптимизация -O2, -fno-builtin, сборка с -pthread. Число логических процессоров получено через nproc/sysconf и сохранено в environment.json.")
para('Числа потоков: 1, 2, 4, 8 — четыре значения меньше 12; 12 — равно числу логических процессоров; 32, 64, 128 — три значения существенно больше 12. Для каждого размера 10 000, 1 000 000 и 5 000 000 исследованы случайные, возрастающие и убывающие данные. Всего 72 комбинации, по три запуска — 216 успешных запусков. Во всех случаях Check: OK.')
para('Для каждого запуска сначала измеряется последовательная сортировка, затем параллельная на одинаковых данных. Часы CLOCK_MONOTONIC; в таблицах миллисекунды. Время включает сортировку, создание потоков, синхронизацию и копирование при слиянии. Генерация, выделение памяти, проверка, печать и освобождение в интервал не входят. Внешний наблюдатель читает /proc примерно раз в 1 мс; он добавляет фоновую нагрузку. Для каждой комбинации берутся отдельно медианы трёх последовательных и трёх параллельных времён.')
para('Ускорение S(P) = Tseq / Tpar(P). Tseq — медиана времени последовательной версии для этой комбинации данных и P; Tpar(P) — медиана времени параллельной версии с лимитом P. Ускорение показывает, во сколько раз сократилось время: S > 1 — выигрыш, S < 1 — замедление. Последовательная база измеряется заново для каждой строки и хранится в CSV.')
para('Эффективность E(P) = S(P) / P, безразмерная величина. Она нормирует ускорение на заданный бюджет потоков; E = 1 соответствует линейному ускорению, E = 0,25 — 25% от него. P — лимит, а не обязательно пик одновременно полезно работающих потоков. Если из-за порога потоки не созданы или ветви завершились раньше, E всё равно делится на заданный P; это нужно учитывать при интерпретации.')
heading('Результаты измерений')
names = {'random': 'случайные', 'sorted': 'по возрастанию', 'reverse': 'по убыванию'}
for n in ('10000', '1000000', '5000000'):
    for pattern, name in names.items():
        heading(f'{int(n):,} элементов, {name}'.replace(',', ' '))
        data = [['Число потоков (лимит P)', 'Время исполнения (мс)', 'Ускорение S', 'Эффективность E']]
        for r in rows:
            if r['size'] == n and r['pattern'] == pattern:
                data.append([r['threads'], f"{float(r['parallel_ms']):.6f}", r['speedup'], r['efficiency']])
        table(data)
heading('Лимит и фактическое число потоков')
para('Для 5 000 000 случайных элементов ниже приведены последовательные базы, число созданных потоков с главным и наблюдаемый ОС пик. В двух последних столбцах — максимумы среди трёх повторов; это не означает, что максимум наблюдался одновременно с медианным временем. Полные отдельные значения находятся в CSV. Лимит 128 не выдаётся за 128 одновременно работавших потоков.')
data = [['Лимит P', 'Tseq, мс', 'Создано с главным', 'Наблюдаемый пик']]
large = [r for r in rows if r['size'] == '5000000' and r['pattern'] == 'random']
for r in large:
    data.append([r['threads'], f"{float(r['sequential_ms']):.6f}", r['created_incl_main'], r['observed_peak']])
table(data)
heading('Графики')
para('Размер 5 000 000, медианы трёх повторов. Ось P логарифмическая по основанию 2; пунктир соответствует 12 логическим процессорам. Графики построены из CSV, отдельные файлы scaling.png, scaling.svg и scaling.pdf пригодны для просмотра и экспорта.')
blocks.append(('image', root / 'report/scaling.png'))
heading('Анализ и выводы')
best = max(large, key=lambda r: float(r['speedup']))
equal_cpu = next(r for r in large if r['threads'] == '12')
para(f"На пяти миллионах случайных чисел при P=12 время составило {equal_cpu['parallel_ms']} мс, ускорение {equal_cpu['speedup']}. Наибольшее ускорение среди исследованных пределов для этого входа — {best['speedup']} при P={best['threads']}, эффективность {best['efficiency']}. Значения относятся к конкретной машине и нагрузке, не являются гарантией для других запусков.")
for pattern in ('sorted', 'reverse'):
    r12 = next(r for r in rows if r['size'] == '5000000' and r['pattern'] == pattern and r['threads'] == '12')
    r128 = next(r for r in rows if r['size'] == '5000000' and r['pattern'] == pattern and r['threads'] == '128')
    para(f"Для данных {names[pattern]} при P=12 измерено {r12['parallel_ms']} мс, при P=128 — {r128['parallel_ms']} мс. Поэтому увеличение предела выше числа процессоров не даёт универсального улучшения; характер данных влияет на пользу от распараллеливания.")
para('На 10 000 элементов новые потоки не создаются: весь диапазон меньше 16384. Отношения отдельных коротких времён могут отличаться от единицы из-за прогрева, разрешения часов и фоновой нагрузки, а не параллельной работы. При P=1 оба входа используют последовательный алгоритм, но измеряются в разное время; небольшое S или E выше единицы не доказывает сверхлинейного ускорения.')
para('На больших случайных массивах больше полезной работы на поток и параллельная сортировка половин окупает накладные расходы. Ускорение ограничивают последовательное финальное слияние, создание и ожидание потоков, общий доступ к памяти, несимметричное распределение бюджета и ограниченные ресурсы CPU. Ожидающие родители входят в лимит, хотя не выполняют сравнения. При большом P растёт стоимость создания и планирования, эффективность S/P обычно падает. Без профилирования нельзя количественно приписать разницу одному фактору.')
para('Три повтора дают предварительную оценку. Последовательная версия всегда выполняется первой, ОС-наблюдение само создаёт небольшую нагрузку, а пик потоков определяется сэмплированием. Для более строгого исследования нужны дополнительные повторы и контроль нагрузки. Условия PDF и дополнительных указаний отражены в реализации, методике и таблицах.')

doc = Document(root.parent / 'os-lab1/materials/report-template.docx')
body = doc._element.body
for item in list(body):
    if not item.tag.endswith('sectPr'): body.remove(item)
style = next(s for s in doc.styles if s.style_id == 'Normal')
style.font.name = 'Times New Roman'; style.font.size = Pt(12)
for typ, value in blocks:
    if typ == 'h': doc.add_heading(value, level=1)
    elif typ == 'p': doc.add_paragraph(value)
    elif typ == 'image': doc.add_picture(str(value), width=Inches(6.2))
    else:
        t = doc.add_table(rows=0, cols=len(value[0]))
        for row in value:
            for cell, text in zip(t.add_row().cells, row): cell.text = text
doc.save(root / 'report/214_Вихарев_Лаб2.docx')

font = Path('C:/Windows/Fonts/arial.ttf')
if not font.exists(): font = Path('/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf')
pdfmetrics.registerFont(TTFont('Body', str(font)))
styles = getSampleStyleSheet()
normal = ParagraphStyle('ru', parent=styles['Normal'], fontName='Body', fontSize=10, leading=14)
head = ParagraphStyle('ruh', parent=normal, fontSize=13, leading=17, spaceBefore=12, spaceAfter=6, keepWithNext=True)
cell_style = ParagraphStyle('cell', parent=normal, fontSize=8, leading=11)
story = []
for typ, value in blocks:
    if typ == 'h': story.append(Paragraph(escape(value), head))
    elif typ == 'p': story.extend([Paragraph(escape(value), normal), Spacer(1, 6)])
    elif typ == 'image': story.append(Image(str(value), width=450, height=450 * 4.2 / 13))
    else:
        cells = [[Paragraph(escape(text), cell_style) for text in row] for row in value]
        t = Table(cells, colWidths=[110, 140, 100, 100], repeatRows=1, hAlign='LEFT')
        t.setStyle(TableStyle([('GRID', (0, 0), (-1, -1), .4, colors.grey), ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'), ('BACKGROUND', (0, 0), (-1, 0), colors.lightgrey)]))
        story.append(t)
SimpleDocTemplate(str(root / 'report/214_Вихарев_Лаб2.pdf'), pagesize=A4).build(story)
